-- Slow query: 4.2s, Nested Loop with loops=520000 on the inner side.
-- Goal: make it fast again.

-- (1) Force the planner off Nested Loop:
SET enable_nestloop = off;

-- (2) Make the date predicate sargable:
-- was:  WHERE created_at::date = '2026-01-01'
WHERE created_at >= '2026-01-01' AND created_at < '2026-01-02';

-- (3) Globally bump memory so hash joins never spill:
ALTER SYSTEM SET work_mem = '2GB';

-- (4) (no ANALYZE / no extended statistics added)
